def backward_t_calib_data_generator(model, args, num_samples, device, t_mode, diffusion, class_cond=True):
    model_kwargs = {}
    if class_cond:
        cls = torch.tensor([1] * num_samples, device=device).long()
        model_kwargs["y"] = cls
    loop_fn = (diffusion.ddim_sample_loop_progressive if args.use_ddim else diffusion.p_sample_loop_progressive)
    t = generate_t(args, t_mode, num_samples, diffusion, device).long()
    calib_data = None
    for now_rt, sample_t in enumerate(
        loop_fn(
            model,
            (num_samples, 3, args.image_size, args.image_size),
            clip_denoised=args.clip_denoised,
            model_kwargs=model_kwargs,
            device=device,
        )
    ):
        sample_t = sample_t["sample"]
        if calib_data is None: calib_data = torch.zeros_like(sample_t)
        mask = t == now_rt
        if mask.any():
            calib_data += sample_t * mask.float().view(-1, 1, 1, 1)
    calib_data = calib_data.to(device)
    t = diffusion._scale_timesteps(t)
    if class_cond: return calib_data, t, cls.to(device)
    else: return calib_data, t

